    30→import {isErrorAborted, toRootHex} from "@lodestar/utils";
    31→import {ZERO_HASH_HEX} from "../../constants/index.js";
    32→import {callInNextEventLoop} from "../../util/eventLoop.js";
    33→import {isOptimisticBlock} from "../../util/forkChoice.js";
    34→import {isQueueErrorAborted} from "../../util/queue/index.js";
    35→import type {BeaconChain} from "../chain.js";
    36→import {ChainEvent, ReorgEventData} from "../emitter.js";
    37→import {ForkchoiceCaller} from "../forkChoice/index.js";
    38→import {REPROCESS_MIN_TIME_TO_NEXT_SLOT_SEC} from "../reprocess.js";
    39→import {toCheckpointHex} from "../stateCache/index.js";
    40→import {AttestationImportOpt, BlockInputType, FullyVerifiedBlock, ImportBlockOpts} from "./types.js";
    41→import {getCheckpointFromState} from "./utils/checkpoint.js";
    42→import {writeBlockInputToDb} from "./writeBlockInputToDb.js";
    43→
    44→/**
    45→ * Fork-choice allows to import attestations from current (0) or past (1) epoch.
    46→ */
    47→const FORK_CHOICE_ATT_EPOCH_LIMIT = 1;
    48→/**
    49→ * Emit eventstream events for block contents events only for blocks that are recent enough to clock
    50→ */
    51→const EVENTSTREAM_EMIT_RECENT_BLOCK_SLOTS = 64;
    52→
    53→/**
    54→ * Imports a fully verified block into the chain state. Produces multiple permanent side-effects.
    55→ *
    56→ * ImportBlock order of operations must guarantee that BeaconNode does not end in an unknown state:
    57→ *
    58→ * 1. Persist block to hot DB (pre-emptively)
    59→ *    - Done before importing block to fork-choice to guarantee that blocks in the fork-choice *always* are persisted
    60→ *      in the DB. Otherwise the beacon node may end up in an unrecoverable state. If a block is persisted in the hot
    61→ *      db but is unknown by the fork-choice, then it will just use some extra disk space. On restart is will be
    62→ *      pruned regardless.
    63→ *    - Note that doing a disk write first introduces a small delay before setting the head. An improvement where disk
    64→ *      write happens latter requires the ability to roll back a fork-choice head change if disk write fails
    65→ *
    66→ * 2. Import block to fork-choice
    67→ * 3. Import attestations to fork-choice
    68→ * 4. Import attester slashings to fork-choice
    69→ * 5. Compute head. If new head, immediately stateCache.setHeadState()
    70→ * 6. Queue notifyForkchoiceUpdate to engine api
    71→ * 7. Add post state to stateCache
    72→ */
    73→export async function importBlock(
    74→  this: BeaconChain,
    75→  fullyVerifiedBlock: FullyVerifiedBlock,
    76→  opts: ImportBlockOpts
    77→): Promise<void> {
    78→  const {blockInput, postState, parentBlockSlot, executionStatus, dataAvailabilityStatus} = fullyVerifiedBlock;
    79→  const {block, source} = blockInput;
    80→  const {slot: blockSlot} = block.message;
    81→  const blockRoot = this.config.getForkTypes(blockSlot).BeaconBlock.hashTreeRoot(block.message);
    82→  const blockRootHex = toRootHex(blockRoot);
    83→  const currentSlot = this.forkChoice.getTime();
    84→  const currentEpoch = computeEpochAtSlot(currentSlot);
    85→  const blockEpoch = computeEpochAtSlot(blockSlot);
    86→  const prevFinalizedEpoch = this.forkChoice.getFinalizedCheckpoint().epoch;
    87→  const blockDelaySec = (fullyVerifiedBlock.seenTimestampSec - postState.genesisTime) % this.config.SECONDS_PER_SLOT;
    88→  const recvToValLatency = Date.now() / 1000 - (opts.seenTimestampSec ?? Date.now() / 1000);
    89→  const fork = this.config.getForkSeq(blockSlot);
    90→
    91→  // this is just a type assertion since blockinput with dataPromise type will not end up here
    92→  if (blockInput.type === BlockInputType.dataPromise) {
    93→    throw Error("Unavailable block can not be imported in forkchoice");
    94→  }
    95→
    96→  // 1. Persist block to hot DB (pre-emptively)
    97→  // If eagerPersistBlock = true we do that in verifyBlocksInEpoch to batch all I/O operations to save block time to head
    98→  if (!opts.eagerPersistBlock) {
    99→    await writeBlockInputToDb.call(this, [blockInput]);
   100→  }
   101→
   102→  // 2. Import block to fork choice
   103→
   104→  // Should compute checkpoint balances before forkchoice.onBlock
   105→  this.checkpointBalancesCache.processState(blockRootHex, postState);
   106→  const blockSummary = this.forkChoice.onBlock(
   107→    block.message,
   108→    postState,
   109→    blockDelaySec,
   110→    currentSlot,
   111→    executionStatus,
   112→    dataAvailabilityStatus
   113→  );
   114→
   115→  // This adds the state necessary to process the next block
   116→  // Some block event handlers require state being in state cache so need to do this before emitting EventType.block
   117→  this.regen.processState(blockRootHex, postState);
   118→
   119→  this.metrics?.importBlock.bySource.inc({source});
   120→  this.logger.verbose("Added block to forkchoice and state cache", {slot: blockSlot, root: blockRootHex});
   121→
   122→  // 3. Import attestations to fork choice
   123→  //
   124→  // - For each attestation
   125→  //   - Get indexed attestation
   126→  //   - Register attestation with fork-choice
   127→  //   - Register attestation with validator monitor (only after sync)
   128→  // Only process attestations of blocks with relevant attestations for the fork-choice:
   129→  // If current epoch is N, and block is epoch X, block may include attestations for epoch X or X - 1.
   130→  // The latest block that is useful is at epoch N - 1 which may include attestations for epoch N - 1 or N - 2.
   131→  if (
   132→    opts.importAttestations === AttestationImportOpt.Force ||
   133→    (opts.importAttestations !== AttestationImportOpt.Skip && blockEpoch >= currentEpoch - FORK_CHOICE_ATT_EPOCH_LIMIT)
   134→  ) {
   135→    const attestations = block.message.body.attestations;
   136→    const rootCache = new RootCache(postState);
   137→    const invalidAttestationErrorsByCode = new Map<string, {error: Error; count: number}>();
   138→
   139→    const addAttestation = fork >= ForkSeq.electra ? addAttestationPostElectra : addAttestationPreElectra;
   140→
   141→    for (const attestation of attestations) {
   142→      try {
   143→        // TODO Electra: figure out how to reuse the attesting indices computed from state transition
   144→        const indexedAttestation = postState.epochCtx.getIndexedAttestation(fork, attestation);
   145→        const {target, beaconBlockRoot} = attestation.data;
   146→
   147→        const attDataRoot = toRootHex(ssz.phase0.AttestationData.hashTreeRoot(indexedAttestation.data));
   148→        addAttestation.call(
   149→          this,
   150→          postState.epochCtx,
   151→          target,
   152→          attDataRoot,
   153→          attestation as Attestation<ForkPostElectra>,
   154→          indexedAttestation
   155→        );
   156→        // Duplicated logic from fork-choice onAttestation validation logic.
   157→        // Attestations outside of this range will be dropped as Errors, so no need to import
   158→        if (
   159→          opts.importAttestations === AttestationImportOpt.Force ||
   160→          (target.epoch <= currentEpoch && target.epoch >= currentEpoch - FORK_CHOICE_ATT_EPOCH_LIMIT)
   161→        ) {
   162→          this.forkChoice.onAttestation(
   163→            indexedAttestation,
   164→            attDataRoot,
   165→            opts.importAttestations === AttestationImportOpt.Force
   166→          );
   167→        }
   168→
   169→        // Note: To avoid slowing down sync, only register attestations within FORK_CHOICE_ATT_EPOCH_LIMIT
   170→        this.seenBlockAttesters.addIndices(blockEpoch, indexedAttestation.attestingIndices);
   171→
   172→        const correctHead = ssz.Root.equals(rootCache.getBlockRootAtSlot(attestation.data.slot), beaconBlockRoot);
   173→        const missedSlotVote = ssz.Root.equals(
   174→          rootCache.getBlockRootAtSlot(attestation.data.slot - 1),
   175→          rootCache.getBlockRootAtSlot(attestation.data.slot)
   176→        );
   177→        this.validatorMonitor?.registerAttestationInBlock(
   178→          indexedAttestation,
   179→          parentBlockSlot,
   180→          correctHead,
   181→          missedSlotVote,
   182→          blockRootHex,
   183→          blockSlot
   184→        );
   185→      } catch (e) {
   186→        // a block has a lot of attestations and it may has same error, we don't want to log all of them
   187→        if (e instanceof ForkChoiceError && e.type.code === ForkChoiceErrorCode.INVALID_ATTESTATION) {
   188→          let errWithCount = invalidAttestationErrorsByCode.get(e.type.err.code);
   189→          if (errWithCount === undefined) {
   190→            errWithCount = {error: e as Error, count: 1};
   191→            invalidAttestationErrorsByCode.set(e.type.err.code, errWithCount);
   192→          } else {
   193→            errWithCount.count++;
   194→          }
   195→        } else {
   196→          // always log other errors
   197→          this.logger.warn("Error processing attestation from block", {slot: blockSlot}, e as Error);
   198→        }
   199→      }
   200→    }
   201→
   202→    for (const {error, count} of invalidAttestationErrorsByCode.values()) {
   203→      this.logger.warn(
   204→        "Error processing attestations from block",
   205→        {slot: blockSlot, erroredAttestations: count},
   206→        error
   207→      );
   208→    }
   209→  }
   210→
   211→  // 4. Import attester slashings to fork choice
   212→  //
   213→  // FORK_CHOICE_ATT_EPOCH_LIMIT is for attestation to become valid
   214→  // but AttesterSlashing could be found before that time and still able to submit valid attestations
   215→  // until slashed validator become inactive, see computeActivationExitEpoch() function
   216→  if (
   217→    opts.importAttestations === AttestationImportOpt.Force ||
   218→    (opts.importAttestations !== AttestationImportOpt.Skip &&
   219→      blockEpoch >= currentEpoch - FORK_CHOICE_ATT_EPOCH_LIMIT - 1 - MAX_SEED_LOOKAHEAD)
   220→  ) {
   221→    for (const slashing of block.message.body.attesterSlashings) {
   222→      try {
   223→        // all AttesterSlashings are valid before reaching this
   224→        this.forkChoice.onAttesterSlashing(slashing);
   225→      } catch (e) {
   226→        this.logger.warn("Error processing AttesterSlashing from block", {slot: blockSlot}, e as Error);
   227→      }
   228→    }
   229→  }
   230→
   231→  // 5. Compute head. If new head, immediately stateCache.setHeadState()
   232→
   233→  const oldHead = this.forkChoice.getHead();
   234→  const newHead = this.recomputeForkChoiceHead(ForkchoiceCaller.importBlock);
   235→  const currFinalizedEpoch = this.forkChoice.getFinalizedCheckpoint().epoch;
   236→
   237→  if (newHead.blockRoot !== oldHead.blockRoot) {
   238→    // Set head state as strong reference
   239→    this.regen.updateHeadState(newHead, postState);
   240→
   241→    try {
   242→      this.emitter.emit(routes.events.EventType.head, {
   243→        block: newHead.blockRoot,
   244→        epochTransition: computeStartSlotAtEpoch(computeEpochAtSlot(newHead.slot)) === newHead.slot,
   245→        slot: newHead.slot,
   246→        state: newHead.stateRoot,
   247→        previousDutyDependentRoot: this.forkChoice.getDependentRoot(newHead, EpochDifference.previous),
   248→        currentDutyDependentRoot: this.forkChoice.getDependentRoot(newHead, EpochDifference.current),
   249→        executionOptimistic: isOptimisticBlock(newHead),
   250→      });
   251→    } catch (e) {
   252→      // getDependentRoot() may fail with error: "No block for root" as we can see in holesky non-finality issue
   253→      this.logger.debug("Error emitting head event", {slot: newHead.slot, root: newHead.blockRoot}, e as Error);
   254→    }
   255→
   256→    const delaySec = this.clock.secFromSlot(newHead.slot);
   257→    this.logger.verbose("New chain head", {
   258→      slot: newHead.slot,
   259→      root: newHead.blockRoot,
   260→      delaySec,
   261→    });
   262→
   263→    if (this.metrics) {
   264→      this.metrics.headSlot.set(newHead.slot);
   265→      // Only track "recent" blocks. Otherwise sync can distort this metrics heavily.
   266→      // We want to track recent blocks coming from gossip, unknown block sync, and API.
   267→      if (delaySec < SLOTS_PER_EPOCH * this.config.SECONDS_PER_SLOT) {
   268→        this.metrics.importBlock.elapsedTimeTillBecomeHead.observe(delaySec);
   269→        if (delaySec > this.config.SECONDS_PER_SLOT / INTERVALS_PER_SLOT) {
   270→          this.metrics.importBlock.setHeadAfterFirstInterval.inc();
   271→        }
   272→      }
   273→    }
   274→
   275→    this.onNewHead(newHead);
   276→
   277→    this.metrics?.forkChoice.changedHead.inc();
   278→
   279→    const ancestorResult = this.forkChoice.getCommonAncestorDepth(oldHead, newHead);
   280→    if (ancestorResult.code === AncestorStatus.CommonAncestor) {
   281→      // CommonAncestor = chain reorg, old head and new head not direct descendants
   282→
   283→      const forkChoiceReorgEventData: ReorgEventData = {
   284→        depth: ancestorResult.depth,
   285→        epoch: computeEpochAtSlot(newHead.slot),
   286→        slot: newHead.slot,
   287→        newHeadBlock: newHead.blockRoot,
   288→        oldHeadBlock: oldHead.blockRoot,
   289→        newHeadState: newHead.stateRoot,
   290→        oldHeadState: oldHead.stateRoot,
   291→        executionOptimistic: isOptimisticBlock(newHead),
   292→      };
   293→
   294→      this.emitter.emit(routes.events.EventType.chainReorg, forkChoiceReorgEventData);
   295→      this.logger.verbose("Chain reorg", forkChoiceReorgEventData);
   296→
   297→      this.metrics?.forkChoice.reorg.inc();
   298→      this.metrics?.forkChoice.reorgDistance.observe(ancestorResult.depth);
   299→    }
   300→
   301→    // Lightclient server support (only after altair)
   302→    // - Persist state witness
   303→    // - Use block's syncAggregate
   304→    if (blockEpoch >= this.config.ALTAIR_FORK_EPOCH) {
   305→      // we want to import block asap so do this in the next event loop
   306→      callInNextEventLoop(() => {
   307→        try {
   308→          this.lightClientServer?.onImportBlockHead(
   309→            block.message as BeaconBlock<ForkPostAltair>,
   310→            postState as CachedBeaconStateAltair,
   311→            parentBlockSlot
   312→          );
   313→        } catch (e) {
   314→          this.logger.verbose("Error lightClientServer.onImportBlock", {slot: blockSlot}, e as Error);
   315→        }
   316→      });
   317→    }
   318→  }
   319→
   320→  // 6. Queue notifyForkchoiceUpdate to engine api
   321→  //
   322→  // NOTE: forkChoice.fsStore.finalizedCheckpoint MUST only change in response to an onBlock event
   323→  // Notifying EL of head and finalized updates as below is usually done within the 1st 4s of the slot.
   324→  // If there is an advanced payload generation in the next slot, we'll notify EL again 4s before next
   325→  // slot via PrepareNextSlotScheduler. There is no harm updating the ELs with same data, it will just ignore it.
   326→
   327→  // Suppress fcu call if shouldOverrideFcu is true. This only happens if we have proposer boost reorg enabled
   328→  // and the block is weak and can potentially be reorged out.
   329→  let shouldOverrideFcu = false;
   330→
   331→  if (blockSlot >= currentSlot && isExecutionStateType(postState)) {
   332→    let notOverrideFcuReason = NotReorgedReason.Unknown;
   333→    const proposalSlot = blockSlot + 1;
   334→    try {
   335→      const proposerIndex = postState.epochCtx.getBeaconProposer(proposalSlot);
   336→      const feeRecipient = this.beaconProposerCache.get(proposerIndex);
   337→
   338→      if (feeRecipient) {
   339→        // We would set this to true if
   340→        //  1) This is a gossip block
   341→        //  2) We are proposer of next slot
   342→        //  3) Proposer boost reorg related flag is turned on (this is checked inside the function)
   343→        //  4) Block meets the criteria of being re-orged out (this is also checked inside the function)
   344→        const result = this.forkChoice.shouldOverrideForkChoiceUpdate(
   345→          blockSummary.blockRoot,
   346→          this.clock.secFromSlot(currentSlot),
   347→          currentSlot
   348→        );
   349→        shouldOverrideFcu = result.shouldOverrideFcu;
   350→        if (!result.shouldOverrideFcu) {
   351→          notOverrideFcuReason = result.reason;
   352→        }
   353→      } else {
   354→        notOverrideFcuReason = NotReorgedReason.NotProposerOfNextSlot;
   355→      }
   356→    } catch (e) {
   357→      if (isStartSlotOfEpoch(proposalSlot)) {
   358→        notOverrideFcuReason = NotReorgedReason.NotShufflingStable;
   359→      } else {
   360→        this.logger.warn("Unable to get beacon proposer. Do not override fcu.", {proposalSlot}, e as Error);
   361→      }
   362→    }
   363→
   364→    if (shouldOverrideFcu) {
   365→      this.logger.verbose("Weak block detected. Skip fcu call in importBlock", {
   366→        blockRoot: blockRootHex,
   367→        slot: blockSlot,
   368→      });
   369→    } else {
   370→      this.metrics?.importBlock.notOverrideFcuReason.inc({reason: notOverrideFcuReason});
   371→      this.logger.verbose("Strong block detected. Not override fcu call", {
   372→        blockRoot: blockRootHex,
   373→        slot: blockSlot,
   374→        reason: notOverrideFcuReason,
   375→      });
   376→    }
   377→  }
   378→
   379→  if (
   380→    !this.opts.disableImportExecutionFcU &&
   381→    (newHead.blockRoot !== oldHead.blockRoot || currFinalizedEpoch !== prevFinalizedEpoch) &&
   382→    !shouldOverrideFcu
   383→  ) {
   384→    /**
   385→     * On post BELLATRIX_EPOCH but pre TTD, blocks include empty execution payload with a zero block hash.
   386→     * The consensus clients must not send notifyForkchoiceUpdate before TTD since the execution client will error.
   387→     * So we must check that:
   388→     * - `headBlockHash !== null` -> Pre BELLATRIX_EPOCH
   389→     * - `headBlockHash !== ZERO_HASH` -> Pre TTD
   390→     */
   391→    const headBlockHash = this.forkChoice.getHead().executionPayloadBlockHash ?? ZERO_HASH_HEX;
   392→    /**
   393→     * After BELLATRIX_EPOCH and TTD it's okay to send a zero hash block hash for the finalized block. This will happen if
   394→     * the current finalized block does not contain any execution payload at all (pre MERGE_EPOCH) or if it contains a
   395→     * zero block hash (pre TTD)
   396→     */
   397→    const safeBlockHash = this.forkChoice.getJustifiedBlock().executionPayloadBlockHash ?? ZERO_HASH_HEX;
   398→    const finalizedBlockHash = this.forkChoice.getFinalizedBlock().executionPayloadBlockHash ?? ZERO_HASH_HEX;
   399→    if (headBlockHash !== ZERO_HASH_HEX) {
   400→      this.executionEngine
   401→        .notifyForkchoiceUpdate(
   402→          this.config.getForkName(this.forkChoice.getHead().slot),
   403→          headBlockHash,
   404→          safeBlockHash,
   405→          finalizedBlockHash
   406→        )
   407→        .catch((e) => {
   408→          if (!isErrorAborted(e) && !isQueueErrorAborted(e)) {
   409→            this.logger.error("Error pushing notifyForkchoiceUpdate()", {headBlockHash, finalizedBlockHash}, e);
   410→          }
   411→        });
   412→    }
   413→  }
   414→
   415→  if (!isStateValidatorsNodesPopulated(postState)) {
   416→    this.logger.verbose("After importBlock caching postState without SSZ cache", {slot: postState.slot});
   417→  }
   418→
   419→  if (blockSlot % SLOTS_PER_EPOCH === 0) {
   420→    // Cache state to preserve epoch transition work
   421→    const checkpointState = postState;
   422→    const cp = getCheckpointFromState(checkpointState);
   423→    this.regen.addCheckpointState(cp, checkpointState);
   424→    // consumers should not mutate or get the transfered cache
   425→    this.emitter.emit(ChainEvent.checkpoint, cp, checkpointState.clone(true));
   426→
   427→    // Note: in-lined code from previos handler of ChainEvent.checkpoint
   428→    this.logger.verbose("Checkpoint processed", toCheckpointHex(cp));
   429→
   430→    const activeValidatorsCount = checkpointState.epochCtx.currentShuffling.activeIndices.length;
   431→    this.metrics?.currentActiveValidators.set(activeValidatorsCount);
   432→    this.metrics?.currentValidators.set({status: "active"}, activeValidatorsCount);
   433→
   434→    const parentBlockSummary = this.forkChoice.getBlock(checkpointState.latestBlockHeader.parentRoot);
   435→
   436→    if (parentBlockSummary) {
   437→      const justifiedCheckpoint = checkpointState.currentJustifiedCheckpoint;
   438→      const justifiedEpoch = justifiedCheckpoint.epoch;
   439→      const preJustifiedEpoch = parentBlockSummary.justifiedEpoch;
   440→      if (justifiedEpoch > preJustifiedEpoch) {
   441→        this.logger.verbose("Checkpoint justified", toCheckpointHex(justifiedCheckpoint));
   442→        this.metrics?.previousJustifiedEpoch.set(checkpointState.previousJustifiedCheckpoint.epoch);
   443→        this.metrics?.currentJustifiedEpoch.set(justifiedCheckpoint.epoch);
   444→      }
   445→      const finalizedCheckpoint = checkpointState.finalizedCheckpoint;
   446→      const finalizedEpoch = finalizedCheckpoint.epoch;
   447→      const preFinalizedEpoch = parentBlockSummary.finalizedEpoch;
   448→      if (finalizedEpoch > preFinalizedEpoch) {
   449→        this.emitter.emit(routes.events.EventType.finalizedCheckpoint, {
   450→          block: toRootHex(finalizedCheckpoint.root),
   451→          epoch: finalizedCheckpoint.epoch,
   452→          state: toRootHex(checkpointState.hashTreeRoot()),
   453→          executionOptimistic: false,
   454→        });
   455→        this.logger.verbose("Checkpoint finalized", toCheckpointHex(finalizedCheckpoint));
   456→        this.metrics?.finalizedEpoch.set(finalizedCheckpoint.epoch);
   457→      }
   458→    }
   459→  }
   460→
   461→  // Send block events, only for recent enough blocks
   462→
   463→  if (currentSlot - blockSlot < EVENTSTREAM_EMIT_RECENT_BLOCK_SLOTS) {
   464→    // We want to import block asap so call all event handler in the next event loop
   465→    callInNextEventLoop(() => {
   466→      // NOTE: Skip emitting if there are no listeners from the API
   467→      if (this.emitter.listenerCount(routes.events.EventType.block)) {
   468→        this.emitter.emit(routes.events.EventType.block, {
   469→          block: blockRootHex,
   470→          slot: blockSlot,
   471→          executionOptimistic: blockSummary != null && isOptimisticBlock(blockSummary),
   472→        });
   473→      }
   474→      if (this.emitter.listenerCount(routes.events.EventType.voluntaryExit)) {
   475→        for (const voluntaryExit of block.message.body.voluntaryExits) {
   476→          this.emitter.emit(routes.events.EventType.voluntaryExit, voluntaryExit);
   477→        }
   478→      }
   479→      if (this.emitter.listenerCount(routes.events.EventType.blsToExecutionChange)) {
   480→        for (const blsToExecutionChange of (block.message as capella.BeaconBlock).body.blsToExecutionChanges ?? []) {
   481→          this.emitter.emit(routes.events.EventType.blsToExecutionChange, blsToExecutionChange);
   482→        }
   483→      }
   484→      if (this.emitter.listenerCount(routes.events.EventType.attestation)) {
   485→        for (const attestation of block.message.body.attestations) {
   486→          this.emitter.emit(routes.events.EventType.attestation, attestation);
   487→        }
   488→      }
   489→      if (this.emitter.listenerCount(routes.events.EventType.attesterSlashing)) {
   490→        for (const attesterSlashing of block.message.body.attesterSlashings) {
   491→          this.emitter.emit(routes.events.EventType.attesterSlashing, attesterSlashing);
   492→        }
   493→      }
   494→      if (this.emitter.listenerCount(routes.events.EventType.proposerSlashing)) {
   495→        for (const proposerSlashing of block.message.body.proposerSlashings) {
   496→          this.emitter.emit(routes.events.EventType.proposerSlashing, proposerSlashing);
   497→        }
   498→      }
   499→    });
   500→  }
   501→
   502→  // Register stat metrics about the block after importing it
   503→  this.metrics?.parentBlockDistance.observe(blockSlot - parentBlockSlot);
   504→  this.metrics?.proposerBalanceDeltaAny.observe(fullyVerifiedBlock.proposerBalanceDelta);
   505→  this.validatorMonitor?.registerImportedBlock(block.message, fullyVerifiedBlock);
   506→  if (this.config.getForkSeq(blockSlot) >= ForkSeq.altair) {
   507→    this.validatorMonitor?.registerSyncAggregateInBlock(
   508→      blockEpoch,
   509→      (block as altair.SignedBeaconBlock).message.body.syncAggregate,
   510→      fullyVerifiedBlock.postState.epochCtx.currentSyncCommitteeIndexed.validatorIndices
   511→    );
   512→  }
   513→  // dataPromise will not end up here, but preDeneb could. In future we might also allow syncing
   514→  // out of data range blocks and import then in forkchoice although one would not be able to
   515→  // attest and propose with such head similar to optimistic sync
   516→  if (
   517→    blockInput.type === BlockInputType.availableData &&
   518→    (blockInput.blockData.fork === ForkName.deneb || blockInput.blockData.fork === ForkName.electra)
   519→  ) {
   520→    const {blobsSource} = blockInput.blockData;
   521→    this.metrics?.importBlock.blobsBySource.inc({blobsSource});
   522→  }
   523→
   524→  const advancedSlot = this.clock.slotWithFutureTolerance(REPROCESS_MIN_TIME_TO_NEXT_SLOT_SEC);
   525→
   526→  // Gossip blocks need to be imported as soon as possible, waiting attestations could be processed
   527→  // in the next event loop. See https://github.com/ChainSafe/lodestar/issues/4789
   528→  callInNextEventLoop(() => {
   529→    this.reprocessController.onBlockImported({slot: blockSlot, root: blockRootHex}, advancedSlot);
   530→  });
   531→
   532→  if (opts.seenTimestampSec !== undefined) {
   533→    const recvToValidation = Date.now() / 1000 - opts.seenTimestampSec;
   534→    const validationTime = recvToValidation - recvToValLatency;
   535→
   536→    this.metrics?.gossipBlock.blockImport.recvToValidation.observe(recvToValidation);
   537→    this.metrics?.gossipBlock.blockImport.validationTime.observe(validationTime);
   538→
   539→    this.logger.debug("Imported block", {slot: blockSlot, recvToValLatency, recvToValidation, validationTime});
   540→  }
   541→
   542→  this.logger.verbose("Block processed", {
   543→    slot: blockSlot,
   544→    root: blockRootHex,
   545→    delaySec: this.clock.secFromSlot(blockSlot),
   546→  });
   547→}
   548→
   549→export function addAttestationPreElectra(
   550→  this: BeaconChain,
   551→  // added to have the same signature as addAttestationPostElectra
   552→  _: EpochCache,
   553→  target: phase0.Checkpoint,
   554→  attDataRoot: string,
   555→  attestation: Attestation,
   556→  indexedAttestation: phase0.IndexedAttestation
   557→): void {
   558→  this.seenAggregatedAttestations.add(
   559→    target.epoch,
   560→    attestation.data.index,
   561→    attDataRoot,
   562→    {aggregationBits: attestation.aggregationBits, trueBitCount: indexedAttestation.attestingIndices.length},
   563→    true
   564→  );
   565→}
   566→
   567→export function addAttestationPostElectra(
   568→  this: BeaconChain,
   569→  epochCtx: EpochCache,
   570→  target: phase0.Checkpoint,
   571→  attDataRoot: string,
   572→  attestation: Attestation<ForkPostElectra>,
   573→  indexedAttestation: electra.IndexedAttestation
   574→): void {
   575→  const committeeIndices = attestation.committeeBits.getTrueBitIndexes();
   576→  if (committeeIndices.length === 1) {
   577→    this.seenAggregatedAttestations.add(
   578→      target.epoch,
   579→      committeeIndices[0],
   580→      attDataRoot,
   581→      {aggregationBits: attestation.aggregationBits, trueBitCount: indexedAttestation.attestingIndices.length},
   582→      true
   583→    );
   584→  } else {
   585→    const committees = epochCtx.getBeaconCommittees(attestation.data.slot, committeeIndices);
   586→    const aggregationBools = attestation.aggregationBits.toBoolArray();
   587→    let offset = 0;
   588→    for (let i = 0; i < committees.length; i++) {
   589→      const committee = committees[i];
   590→      const aggregationBits = BitArray.fromBoolArray(aggregationBools.slice(offset, offset + committee.length));
   591→      const trueBitCount = aggregationBits.getTrueBitIndexes().length;
   592→      offset += committee.length;
   593→      this.seenAggregatedAttestations.add(
   594→        target.epoch,
   595→        committeeIndices[i],
   596→        attDataRoot,
   597→        {aggregationBits, trueBitCount},
   598→        true
   599→      );
   600→    }
   601→  }
   602→}
   603→

