    28→}
    29→
    30→interface CachedDataItem {
    31→  cacheId: number;
    32→}
    33→type Availability<T> = {
    34→  availabilityPromise: Promise<T>;
    35→  resolveAvailability: (data: T) => void;
    36→};
    37→
    38→/**
    39→ *
    40→ * Deneb Blob Format Types
    41→ *
    42→ */
    43→/** Enum to represent where blobs come from */
    44→export enum BlobsSource {
